                    <img className="w-full h-76 block max-w-full grow shrink-0 basis-[0%] overflow-clip object-cover aspect-[auto_700/320] align-bottom max-md:h-[9.3125rem] md:max-lg:h-[20.5625rem] 2xl:h-[19.1875rem]" data-ditto-id="style-span-11" data-component="image" alt="Someone using the Buffer Interface to schedule posts." height="320" sizes="auto, (max-width: 700px) 100vw, 700px" src="/assets/cloned/images/0c897c338ba4.jpg" srcSet="/assets/cloned/images/0c897c338ba4.jpg 700w, /assets/cloned/images/4195b334c1b7.jpg 350w" width="700" />
